// Custom-domain verification lifecycle — single source of truth.
//
// A studio can point its own domain (e.g. www.theirstudio.com) at Studio Nexis.
// The domain only takes over the studio's public URL once it is fully
// provisioned (DNS pointed here + TLS cert issued + nginx serving it). Until
// then every booking/website link keeps using the safe <slug>.<base> subdomain
// (see lib/site-url.ts). This module owns the state machine both the app (UI,
// verify route, cron) and the operator provisioner script agree on.
//
// Pure + dependency-free so it is safe to import from client components, server
// actions, route handlers and the worker alike.

/**
 * Lifecycle states, in order:
 *   PENDING    — domain saved; DNS not (yet) pointing at this server.
 *   VERIFYING  — DNS confirmed pointing here; awaiting cert + nginx provisioning.
 *   LIVE       — cert issued, nginx serving it, smoke test passed. Public URL
 *                switches to the custom domain (the ONLY status site-url trusts).
 *   FAILED     — DNS points elsewhere, cert/nginx failed, or a previously-LIVE
 *                domain stopped resolving here. We fall back to the subdomain.
 */
export type DomainStatus = "PENDING" | "VERIFYING" | "LIVE" | "FAILED";

export type DomainPolicy = {
  status: DomainStatus;
  /** Short human-readable reason when status is FAILED. */
  error?: string | null;
  /** ISO timestamp of the last DNS/provisioning check. */
  checkedAt?: string | null;
};

/** Shape of the `policies` JSON blob we care about here. */
type PoliciesWithDomain = { domain?: unknown } | null | undefined;

/**
 * Legacy statuses predate this module. Map them onto the canonical machine so
 * old rows (and the provisioner, mid-migration) keep rendering correctly:
 *   PENDING_DNS -> PENDING,  ERROR -> FAILED.
 */
export function normalizeDomainStatus(raw: unknown): DomainStatus | null {
  switch (String(raw ?? "")) {
    case "PENDING":
    case "PENDING_DNS":
      return "PENDING";
    case "VERIFYING":
      return "VERIFYING";
    case "LIVE":
      return "LIVE";
    case "FAILED":
    case "ERROR":
      return "FAILED";
    default:
      return null;
  }
}

/** Read + normalize the domain policy off a tenant's `policies` JSON. */
export function domainPolicyOf(policies: unknown): DomainPolicy | null {
  const raw = (policies as PoliciesWithDomain)?.domain as
    | Record<string, unknown>
    | undefined;
  if (!raw) return null;
  const status = normalizeDomainStatus(raw.status);
  if (!status) return null;
  return {
    status,
    error: (raw.error as string | null | undefined) ?? null,
    checkedAt: (raw.checkedAt as string | null | undefined) ?? null,
  };
}

/** True only when the custom domain is fully live and safe to link to. */
export function isDomainLive(policies: unknown): boolean {
  return domainPolicyOf(policies)?.status === "LIVE";
}

/**
 * Normalize a domain string entered by a studio: lower-case, strip scheme,
 * path, port, whitespace and a trailing dot. Returns "" for empty input.
 */
export function normalizeDomain(input: string): string {
  return String(input ?? "")
    .trim()
    .toLowerCase()
    .replace(/^https?:\/\//, "")
    .replace(/\/.*$/, "")
    .replace(/:.*$/, "")
    .replace(/\.$/, "");
}

/**
 * A registrable custom domain: at least two labels, letters/digits/hyphens,
 * no leading hyphen. Deliberately shell-inert (matches the provisioner's own
 * allowlist) so a domain string can never carry shell metacharacters into the
 * operator scripts that interpolate it into certbot/nginx commands.
 */
const DOMAIN_RE = /^(?!-)[a-z0-9-]+(?:\.[a-z0-9-]+)+$/;

export function isValidCustomDomain(domain: string): boolean {
  return (
    DOMAIN_RE.test(domain) &&
    domain.length <= 253 &&
    !domain.includes("..") &&
    domain.split(".").every((l) => l.length >= 1 && l.length <= 63)
  );
}

/** Build the domain policy object to persist for a given status. */
export function makeDomainPolicy(
  status: DomainStatus,
  error?: string | null,
): DomainPolicy {
  return { status, error: error ?? null, checkedAt: new Date().toISOString() };
}

// ── Custom-domain provisioning targets ────────────────────────────────────
// What a studio must point its own domain at for us to serve it. The A-record
// IP is this server's public address; the CNAME host is a name that already
// resolves here (covered by the wildcard cert). Both are configurable per
// deployment so a server migration is an env change, not a code change.
// NEXT_PUBLIC_ so the Settings UI (client) can show the exact record to create.
export const DOMAIN_TARGET_IP =
  process.env.NEXT_PUBLIC_DOMAIN_TARGET_IP ?? "51.79.226.215";
export const DOMAIN_TARGET_HOST =
  process.env.NEXT_PUBLIC_DOMAIN_TARGET_HOST ?? `app.${BASE_DOMAIN}`;

// Server-only DNS verification for custom domains. NEVER import from a client
// component — it uses node:dns. It answers one question: does this domain
// actually resolve to THIS server right now? The answer drives the lifecycle
// (PENDING → VERIFYING, and the LIVE → FAILED safety re-check). It performs no
// mutation and issues no cert; the operator provisioner does that (see
// scripts/domain-provisioner.sh).
import { promises as dns } from "node:dns";
import { DOMAIN_TARGET_IP, DOMAIN_TARGET_HOST } from "@/lib/config";
import { isValidCustomDomain } from "@/lib/domain";

export type DnsCheck =
  | { pointsHere: true; via: "A" | "CNAME"; addresses: string[] }
  | { pointsHere: false; reason: string; addresses: string[] };

/**
 * Resolve `domain` and decide whether it points at this server.
 *
 * Accepts either:
 *   • an A record equal to DOMAIN_TARGET_IP, or
 *   • a CNAME to DOMAIN_TARGET_HOST (or any name that itself resolves to our IP
 *     — resolve4 follows the CNAME chain, so this is covered by the A check).
 *
 * A domain that resolves to some OTHER address is treated as "points
 * elsewhere" — we must never provision a cert for a name we don't control.
 */
export async function checkDomainDns(domain: string): Promise<DnsCheck> {
  if (!isValidCustomDomain(domain)) {
    return { pointsHere: false, reason: "invalid domain", addresses: [] };
  }

  // CNAME to our canonical host is an explicit, unambiguous "yes".
  try {
    const cnames = await dns.resolveCname(domain);
    if (cnames.some((c) => c.replace(/\.$/, "").toLowerCase() === DOMAIN_TARGET_HOST)) {
      return { pointsHere: true, via: "CNAME", addresses: cnames };
    }
  } catch {
    /* no CNAME — fall through to A-record check */
  }

  let addresses: string[] = [];
  try {
    // resolve4 follows any CNAME chain and returns the final A records, so this
    // also covers "CNAME to a host that resolves to our IP".
    addresses = await dns.resolve4(domain);
  } catch (e: unknown) {
    const code = (e as { code?: string })?.code ?? "";
    if (code === "ENOTFOUND" || code === "ENODATA") {
      return { pointsHere: false, reason: "no DNS record yet", addresses: [] };
    }
    return { pointsHere: false, reason: "DNS lookup failed", addresses: [] };
  }

  if (addresses.includes(DOMAIN_TARGET_IP)) {
    return { pointsHere: true, via: "A", addresses };
  }
  return {
    pointsHere: false,
    reason: `points to ${addresses.join(", ") || "nowhere"} (expected ${DOMAIN_TARGET_IP})`,
    addresses,
  };
}

import { NextResponse } from "next/server";
import { Prisma } from "@prisma/client";
import { db } from "@/lib/db";
import { getSession } from "@/lib/auth";
import { externalUrl } from "@/lib/request-url";
import { guardCap } from "@/lib/rbac-server";
import { hasFeature } from "@/lib/features";
import { audit } from "@/lib/hq";
import { domainPolicyOf, makeDomainPolicy } from "@/lib/domain";
import { checkDomainDns } from "@/lib/domain-verify";

// "Verify now" from the Settings → Domain tab. Runs a live DNS check and
// advances the lifecycle:
//   points here + not live  -> VERIFYING (operator provisioner will issue the
//                              cert + nginx vhost and flip it LIVE)
//   points here + live      -> stays LIVE (re-affirms the check timestamp)
//   no record yet           -> PENDING (keep waiting)
//   points elsewhere/invalid-> FAILED (with a short reason)
// It never issues a certificate or touches nginx — that requires root and is
// done out-of-band by scripts/domain-provisioner.sh.
export async function POST(req: Request) {
  const denied = await guardCap(req, "manage_settings");
  if (denied) return denied;
  const auth = await getSession();
  if (!auth || ["STAFF", "INSTRUCTOR"].includes(auth.role)) {
    return NextResponse.redirect(externalUrl(req, "/login"), 303);
  }

  const tenant = await db.tenant.findUniqueOrThrow({ where: { id: auth.tenantId } });
  const back = "/settings?tab=domain";

  if (!hasFeature(tenant, "custom-domain") || !tenant.customDomain) {
    return NextResponse.redirect(externalUrl(req, `${back}&error=domain`), 303);
  }

  const prev = (tenant.policies ?? {}) as Record<string, unknown>;
  const wasLive = domainPolicyOf(tenant.policies)?.status === "LIVE";
  const check = await checkDomainDns(tenant.customDomain);

  let policy;
  if (check.pointsHere) {
    policy = makeDomainPolicy(wasLive ? "LIVE" : "VERIFYING");
  } else if (check.reason === "no DNS record yet") {
    policy = makeDomainPolicy("PENDING");
  } else {
    policy = makeDomainPolicy("FAILED", check.reason);
  }

  await db.tenant.update({
    where: { id: tenant.id },
    data: { policies: { ...prev, domain: policy } as Prisma.InputJsonValue },
  });
  audit({
    tenantId: tenant.id,
    actor: auth.name,
    role: auth.role,
    action: "domain-verify",
    detail: `${tenant.customDomain} → ${policy.status}`,
  });

  return NextResponse.redirect(externalUrl(req, `${back}&verified=${policy.status}`), 303);
}

import { NextResponse } from "next/server";
import { Prisma } from "@prisma/client";
import { db } from "@/lib/db";
import { domainPolicyOf, makeDomainPolicy } from "@/lib/domain";
import { checkDomainDns } from "@/lib/domain-verify";

// Periodic DNS re-check for every studio custom domain. This is the root-free
// half of the lifecycle — it only touches the DB, never certbot/nginx — so it
// can run from the app on a plain cron (curl with CRON_TOKEN). It:
//   • promotes PENDING → VERIFYING once DNS starts pointing here (so the
//     operator provisioner picks it up on its next run), and
//   • demotes LIVE → FAILED the moment a live domain stops resolving here, so
//     site-url.ts immediately falls back to the <slug>.<base> subdomain instead
//     of serving a dead custom domain.
// It deliberately does NOT promote VERIFYING → LIVE: that transition means a
// cert was issued and nginx is serving the domain, which only the root
// provisioner (scripts/domain-provisioner.sh) can attest to.
export async function POST(req: Request) {
  const token = new URL(req.url).searchParams.get("token");
  if (!token || token !== process.env.CRON_TOKEN) {
    return NextResponse.json({ error: "unauthorized" }, { status: 401 });
  }

  const tenants = await db.tenant.findMany({
    where: { customDomain: { not: null } },
    select: { id: true, customDomain: true, policies: true },
  });

  const changes: { domain: string; from: string | null; to: string }[] = [];

  for (const t of tenants) {
    const domain = t.customDomain!;
    const cur = domainPolicyOf(t.policies)?.status ?? null;
    const check = await checkDomainDns(domain);

    let next: ReturnType<typeof makeDomainPolicy> | null = null;
    if (cur === "LIVE") {
      // Safety fallback: a live domain that no longer points here is broken.
      if (!check.pointsHere) next = makeDomainPolicy("FAILED", check.reason);
    } else if (cur === "PENDING" || cur === null) {
      if (check.pointsHere) next = makeDomainPolicy("VERIFYING");
    } else if (cur === "FAILED") {
      // Recovered: DNS now points here again → hand back to the provisioner.
      if (check.pointsHere) next = makeDomainPolicy("VERIFYING");
    }
    // VERIFYING is left untouched — the provisioner owns VERIFYING → LIVE/FAILED.

    if (next) {
      const prev = (t.policies ?? {}) as Record<string, unknown>;
      await db.tenant.update({
        where: { id: t.id },
        data: { policies: { ...prev, domain: next } as Prisma.InputJsonValue },
      });
      changes.push({ domain, from: cur, to: next.status });
    }
  }

  return NextResponse.json({ ok: true, checked: tenants.length, changes });
}

